css.prodRules:
.sand-virtual-transcript .sand-transcript-row {
  display: flex;
  min-width: 0;
}
.sand-virtual-transcript .sand-transcript-row[data-role="user"] {
  justify-content: flex-end;
}
.sand-virtual-transcript .sand-transcript-row[data-role="assistant"] {
  justify-content: flex-start;
}
.sand-virtual-transcript .sand-transcript-row > .sand-message-action-anchor {
  width: auto;
  max-width: min(88%, 640px, calc(100% - 82px));
  min-width: 0;
}
.sand-virtual-transcript .sand-transcript-row > .sand-message-action-anchor > .sand-message {
  width: auto;
  max-width: 100%;
}


/* Canonical ConversationWorkspace forward surface.
 * New styles bind to Fabushi semantic names first; cursor/sand values are compatibility fallbacks. */
.fabushi-forward-dialog {
  width: min(520px, calc(100vw - 24px));
  max-height: min(680px, calc(100vh - 24px));
  overflow: hidden;
